// All Look Different? — border desk game.
// FACES comes from faces.js (generated by scripts/build.py).

const LEADERBOARD_API = 'https://alllookdifferent-leaderboard.c2k-projects.workers.dev';
const PER_COUNTRY = 6;
const QUESTIONS = PER_COUNTRY * 3; // 18; the leaderboard worker caps scores at this

const COUNTRIES = {
    british: { label: 'British', mrz: 'GBR' },
    german:  { label: 'German',  mrz: 'D<<' },
    french:  { label: 'French',  mrz: 'FRA' },
};
const ORDER = ['british', 'german', 'french'];

const $ = id => document.getElementById(id);
const el = (tag, props = {}, ...kids) => {
    const n = Object.assign(document.createElement(tag), props);
    kids.flat().forEach(k => n.append(k));
    return n;
};

// ---------- State ----------
let queue = [];
let current = 0;
let answers = [];
let locked = false;
let playerName = 'Officer';
let saved = false;
let lastSaved = null;

// ---------- Screens ----------
function showScreen(id) {
    document.querySelectorAll('.screen').forEach(s => s.classList.toggle('active', s.id === id));
    if (id === 'leaderboard-screen') loadRoster();
    if (id === 'credits-screen') renderCredits();
    window.scrollTo({ top: 0 });
}
document.addEventListener('click', e => {
    const t = e.target.closest('[data-goto]');
    if (t) showScreen(t.dataset.goto);
});

// ---------- Helpers ----------
function shuffle(a) {
    const s = [...a];
    for (let i = s.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [s[i], s[j]] = [s[j], s[i]];
    }
    return s;
}

function buildQueue() {
    const picks = ORDER.flatMap(nat => shuffle(FACES.filter(f => f.nationality === nat)).slice(0, PER_COUNTRY));
    return shuffle(picks);
}

function mrzLine(face) {
    if (!face) return 'P<EUR' + '<'.repeat(39);
    const parts = face.name.toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Z ]/g, '').trim().split(/\s+/);
    const surname = parts.pop() || '';
    const line = `P<${COUNTRIES[face.nationality].mrz}${surname}<<${parts.join('<')}`;
    return (line + '<'.repeat(44)).slice(0, 44);
}

function today() {
    return new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}

// ---------- Game ----------
function preload(face) {
    if (face) new Image().src = face.image;
}

function startShift(e) {
    e?.preventDefault();
    playerName = $('player-name').value.trim() || 'Officer';
    queue = buildQueue();
    current = 0;
    answers = [];
    saved = false;
    const dots = $('queue-dots');
    dots.replaceChildren(...queue.map(() => el('li')));
    showScreen('quiz-screen');
    loadTraveller();
}

function loadTraveller() {
    const face = queue[current];
    locked = false;
    $('progress-number').textContent = current + 1;
    [...$('queue-dots').children].forEach((d, i) => d.classList.toggle('now', i === current));

    const img = $('person-photo');
    img.src = face.image;
    img.alt = `Passport photo of traveller ${current + 1}`;

    $('field-name').replaceChildren(el('span', { className: 'redacted', textContent: 'Withheld name' }));
    $('field-born').replaceChildren(el('span', { className: 'redacted', textContent: '0000' }));
    const nat = $('field-nat');
    nat.className = 'field-nat';
    nat.textContent = 'To be stamped';
    $('stamp-zone').replaceChildren();
    $('mrz').textContent = mrzLine(null);

    document.querySelectorAll('.stamp-btn').forEach(b => (b.disabled = false));
    preload(queue[current + 1]);
}

function stamp(choice) {
    if (locked) return;
    locked = true;
    const face = queue[current];
    const right = choice === face.nationality;
    answers.push({ face, choice, right });

    document.querySelectorAll('.stamp-btn').forEach(b => (b.disabled = true));

    // The impression lands where your hand put it: a little off-centre, a little crooked.
    const zone = $('stamp-zone');
    const imp = el('div', { className: `impression ${choice}` },
        el('div', {}, el('b', { textContent: COUNTRIES[choice].label }), el('small', { textContent: today() })));
    imp.style.setProperty('--rot', `${(Math.random() * 24 - 12).toFixed(1)}deg`);
    imp.style.left = `${45 + Math.random() * 10}%`;
    zone.append(imp);
    if (!right) zone.append(el('div', { className: 'void', textContent: 'Void' }));

    const passport = $('passport');
    passport.classList.remove('jolt');
    void passport.offsetWidth;
    passport.classList.add('jolt');

    // Reveal the page.
    $('field-name').textContent = face.name;
    $('field-born').textContent = face.born;
    const nat = $('field-nat');
    nat.className = `field-nat revealed ${face.nationality}`;
    nat.textContent = COUNTRIES[face.nationality].label;
    $('mrz').textContent = mrzLine(face);

    const dot = $('queue-dots').children[current];
    dot.classList.remove('now');
    dot.classList.add(right ? 'right' : 'wrong');

    setTimeout(() => {
        current++;
        current < queue.length ? loadTraveller() : showReport();
    }, right ? 1100 : 1700);
}

document.querySelectorAll('.stamp-btn').forEach(b => b.addEventListener('click', () => stamp(b.dataset.answer)));

document.addEventListener('keydown', e => {
    if (!$('quiz-screen').classList.contains('active') || e.metaKey || e.ctrlKey || e.altKey) return;
    const map = { '1': 'british', '2': 'german', '3': 'french', b: 'british', g: 'german', f: 'french' };
    const choice = map[e.key.toLowerCase()];
    if (choice) stamp(choice);
});

// ---------- Report ----------
function verdict(n) {
    if (n === QUESTIONS) return 'Not one got past you. Suspiciously good.';
    if (n >= 15) return 'Sharp eyes. A couple slipped through.';
    if (n >= 12) return 'Well beyond guessing. You can tell them apart.';
    if (n >= 9) return 'Somewhat better than guessing.';
    if (n >= 6) return 'About what guessing would get you. Three countries, one in three.';
    return 'Worse than guessing. They all look the same to you, then.';
}

function creditLine(face) {
    const a = el('a', { href: face.source, textContent: face.license, target: '_blank', rel: 'noopener' });
    return el('span', { className: 'credit' }, `Photo: ${face.author}, `, a);
}

function showReport() {
    const score = answers.filter(a => a.right).length;
    $('score').textContent = score;
    $('report-name').textContent = playerName;
    $('score-message').textContent = verdict(score);

    const save = $('save-score-btn');
    save.disabled = false;
    save.textContent = 'Add me to the roster';
    $('save-status').textContent = '';
    $('save-status').className = 'save-status';

    $('results-breakdown').replaceChildren(...answers.map(({ face, choice, right }) => {
        const thumb = el('div', { className: 'thumb' },
            el('img', { src: face.image, alt: face.name, loading: 'lazy' }),
            el('span', { className: `mark ${right ? 'right' : 'wrong'}`, textContent: right ? '✓' : '✗', title: right ? 'Stamped correctly' : 'Wrong stamp' }));
        const who = el('div', { className: 'who' },
            el('a', { href: face.wikidata, textContent: face.name, target: '_blank', rel: 'noopener' }));
        const said = el('div', { className: 'said',
            textContent: right ? COUNTRIES[face.nationality].label : `${COUNTRIES[face.nationality].label}, you stamped ${COUNTRIES[choice].label}` });
        return el('li', {}, thumb, who, said, creditLine(face));
    }));

    showScreen('results-screen');
}

$('start-form').addEventListener('submit', startShift);
$('retry-btn').addEventListener('click', () => startShift());

// ---------- Duty roster ----------
async function saveScore() {
    if (saved) return;
    const btn = $('save-score-btn');
    const status = $('save-status');
    btn.disabled = true;
    btn.textContent = 'Adding you…';
    const score = answers.filter(a => a.right).length;
    try {
        const res = await fetch(`${LEADERBOARD_API}/leaderboard`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name: playerName, score }),
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
        saved = true;
        lastSaved = data.entry;
        btn.textContent = 'On the roster';
        status.className = 'save-status ok';
        status.textContent = data.rank > 0
            ? `You're number ${data.rank} on the roster.`
            : 'Saved, but the roster only keeps the top fifty shifts.';
    } catch (err) {
        btn.disabled = false;
        btn.textContent = 'Add me to the roster';
        status.className = 'save-status err';
        status.textContent = `Your score wasn't saved (${err.message}). Try again.`;
    }
}
$('save-score-btn').addEventListener('click', saveScore);

async function loadRoster() {
    const list = $('leaderboard-list');
    const [loading, empty, error] = ['leaderboard-loading', 'leaderboard-empty', 'leaderboard-error'].map($);
    list.replaceChildren();
    loading.hidden = false;
    empty.hidden = true;
    error.hidden = true;
    try {
        const res = await fetch(`${LEADERBOARD_API}/leaderboard`);
        if (!res.ok) throw new Error(res.status);
        const rows = await res.json();
        loading.hidden = true;
        if (!rows.length) { empty.hidden = false; return; }
        list.replaceChildren(...rows.map(r => {
            const me = lastSaved && r.name === lastSaved.name && r.date === lastSaved.date;
            return el('li', { className: me ? 'me' : '' },
                el('span', { textContent: r.name }),
                el('span', { className: 'r-date', textContent: new Date(r.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) }),
                el('span', { className: 'r-score', textContent: `${r.score}/${QUESTIONS}` }));
        }));
    } catch {
        loading.hidden = true;
        error.hidden = false;
    }
}

// ---------- Credits ----------
let creditsRendered = false;
function renderCredits() {
    if (creditsRendered) return;
    creditsRendered = true;
    const sorted = [...FACES].sort((a, b) => a.name.localeCompare(b.name));
    $('credits-list').replaceChildren(...sorted.map(f => el('li', {},
        el('a', { href: f.wikidata, textContent: f.name, target: '_blank', rel: 'noopener' }),
        ` (${COUNTRIES[f.nationality].label}). Photo: ${f.author}, `,
        el('a', { href: f.source, textContent: f.license, target: '_blank', rel: 'noopener' }))));
}
